#[test]
fn encode_matches_cpp_golden_vectors() {
    for (input, padded, omitted) in ENCODE_GOLDEN {
        assert_eq!(
            base32_encode(input, Base32EncodePolicy::IncludePadding),
            *padded,
            "padded, input = {input:02x?}"
        );
        assert_eq!(
            base32_encode(input, Base32EncodePolicy::OmitPadding),
            *omitted,
            "omitted, input = {input:02x?}"
        );
    }
}

#[test]
fn decode_matches_cpp_golden_vectors() {
    for (input, expected) in DECODE_GOLDEN {
        assert_eq!(base32_decode(input.as_bytes()), *expected, "input = {input:?}");
    }
}
